#define MAX_N 200005

int head[MAX_N], to[MAX_N * 2], nxt[MAX_N * 2];
int edge_cnt;

void add_edge(int u, int v) {
    to[edge_cnt] = v;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt++;
}

int dfs(int u, int parent, int depth) {
    int xor_val = depth % 2;
    for (int e = head[u]; e != -1; e = nxt[e]) {
        int v = to[e];
        if (v == parent) continue;
        xor_val ^= dfs(v, u, depth + 1);
    }
    return xor_val;
}

