typedef long long ll;

typedef struct Edge {
    int to, next;
} Edge;

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int M = 2 * (N - 1);
    Edge *edges = (Edge *)malloc(sizeof(Edge) * M);
    int *head = (int *)malloc(sizeof(int) * (N + 1));
    int *deg = (int *)malloc(sizeof(int) * (N + 1));
    int *xorv = (int *)malloc(sizeof(int) * (N + 1));
    int *queue = (int *)malloc(sizeof(int) * (N + 5));

    for (int i = 1; i <= N; i++) {
        head[i] = -1;
        deg[i] = 0;
        xorv[i] = 0;
    }

    int ecnt = 0;
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);

        edges[ecnt].to = b;
        edges[ecnt].next = head[a];
        head[a] = ecnt++;

        edges[ecnt].to = a;
        edges[ecnt].next = head[b];
        head[b] = ecnt++;

        deg[a]++;
        deg[b]++;
        xorv[a] ^= b;
        xorv[b] ^= a;
    }

    if (N == 1) {
        puts("Takahashi");
        free(edges);
        free(head);
        free(deg);
        free(xorv);
        free(queue);
        return 0;
    }

    int front = 0, back = 0;
    for (int i = 1; i <= N; i++) {
        if (deg[i] <= 1) queue[back++] = i;
    }

    ll moves = 0;
    while (front < back) {
        int v = queue[front++];
        if (deg[v] == 0) continue;

        int u = xorv[v];   // the only alive neighbor
        moves++;           // edge (v,u) is removed in this peeling step

        deg[v] = 0;

        if (deg[u] > 0) {
            deg[u]--;
            xorv[u] ^= v;
            if (deg[u] == 1) queue[back++] = u;
        }
    }

    if (moves % 2 == 1) puts("Takahashi");
    else puts("Aoki");

    free(edges);
    free(head);
    free(deg);
    free(xorv);
    free(queue);
    return 0;
}

