    g = [[] for _ in range(N)]
    for _ in range(N - 1):
        a, b = map(int, input().split())
        g[a - 1].append(b - 1)
        g[b - 1].append(a - 1)

    # Find the diameter of the tree
    def dfs(u, p):
        d = -1
        far = u
        stack = [(u, p, 0)]
        while stack:
            u, p, dist = stack.pop()
            if dist > d:
                d = dist
                far = u
            for v in g[u]:
                if v != p:
                    stack.append((v, u, dist + 1))
        return far, d

    u, _ = dfs(0, -1)
    v, diameter = dfs(u, -1)

    # The winner depends on the diameter
    if diameter % 3 != 1:
        print("Takahashi")
    else:
        print("Aoki")

