import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N;
    static ArrayList<Integer>[] g;
    static int[] parent, order, depth;
    static int[] down, up;
    static int[] max1Val, max2Val, max1Child;
    static int[] grundy;
    static final int[] EMPTY = new int[0];

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();
        for (int i = 0; i < N - 1; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            g[a].add(b);
            g[b].add(a);
        }

        buildTreeAndDepth();
        computeDown();
        computeUpAndEccentricity();

        int maxEcc = 0;
        for (int i = 0; i < N; i++) maxEcc = Math.max(maxEcc, Math.max(down[i], up[i]));

        // Layers by eccentricity parity/game recurrence:
        // Grundy of a vertex depends on neighbors with strictly larger eccentricity.
        // On a tree, eccentricities differ by at most 1 across an edge.
        // So moves from v go only to neighbors with ecc = ecc(v)+1 after one global shift.
        //
        // Recurrence:
        // g(v) = mex({ g(u) | ecc(u) = ecc(v)+1 and u adjacent to v })
        //
        // Since degree can be large but the set size is small in practice on trees under this recurrence,
        // compute directly.
        int[] ecc = new int[N];
        ArrayList<Integer>[] byEcc = new ArrayList[maxEcc + 1];
        for (int i = 0; i <= maxEcc; i++) byEcc[i] = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            ecc[i] = Math.max(down[i], up[i]);
            byEcc[ecc[i]].add(i);
        }

        grundy = new int[N];
        for (int e = maxEcc; e >= 0; e--) {
            for (int v : byEcc[e]) {
                // collect grundy of neighbors with ecc = e+1
                int deg = g[v].size();
                boolean[] seen = new boolean[deg + 2];
                for (int u : g[v]) {
                    if (ecc[u] == e + 1) {
                        int x = grundy[u];
                        if (x < seen.length) seen[x] = true;
                    }
                }
                int mex = 0;
                while (mex < seen.length && seen[mex]) mex++;
                grundy[v] = mex;
            }
        }

        int xor = 0;
        for (int i = 0; i < N; i++) xor ^= grundy[i];

        System.out.println(xor != 0 ? "Takahashi" : "Aoki");
    }

    static void buildTreeAndDepth() {
        parent = new int[N];
        depth = new int[N];
        order = new int[N];
        Arrays.fill(parent, -1);

        int[] stack = new int[N];
        int top = 0, idx = 0;
        stack[top++] = 0;
        parent[0] = -2;

        while (top > 0) {
            int v = stack[--top];
            order[idx++] = v;
            for (int to : g[v]) {
                if (parent[to] == -1) {
                    parent[to] = v;
                    depth[to] = depth[v] + 1;
                    stack[top++] = to;
                }
            }
        }
        parent[0] = -1;
    }

    static void computeDown() {
        down = new int[N];
        max1Val = new int[N];
        max2Val = new int[N];
        max1Child = new int[N];
        Arrays.fill(max1Child, -1);

        for (int i = N - 1; i >= 0; i--) {
            int v = order[i];
            int best1 = -1, best2 = -1, child1 = -1;
            for (int to : g[v]) {
                if (to == parent[v]) continue;
                int val = down[to] + 1;
                if (val > best1) {
                    best2 = best1;
                    best1 = val;
                    child1 = to;
                } else if (val > best2) {
                    best2 = val;
                }
            }
            max1Val[v] = best1;
            max2Val[v] = best2;
            max1Child[v] = child1;
            down[v] = Math.max(0, best1);
        }
    }

    static void computeUpAndEccentricity() {
        up = new int[N];
        up[0] = 0;
        for (int i = 0; i < N; i++) {
            int v = order[i];
            for (int to : g[v]) {
                if (to == parent[v]) continue;
                int useSibling = (max1Child[v] == to ? max2Val[v] : max1Val[v]);
                int bestViaV = Math.max(up[v], Math.max(0, useSibling));
                up[to] = bestViaV + 1;
            }
        }
    }
}

