int n;
vector<int> adj[200005];
int match_size = 0;
// dp[v] = 1 if v is matched in the subtree rooted at v (greedy from leaves)
// Returns true if vertex v is unmatched (available to match with parent)
bool dfs(int v, int parent) {
    bool available = false;
    // First, process children
    // If any child is available, match it with v
    bool matched = false;
    for (int u : adj[v]) {
        if (u == parent) continue;
        bool child_avail = dfs(u, v);
        if (!matched && child_avail) {
            matched = true;
            match_size++;
        }
    }
    return !matched; // v is available if it didn't get matched with a child
}

