#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<vector<int>> g(N);
    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    if (N == 1) {
        cout << "Takahashi\n";
        return 0;
    }

    // Find one endpoint of the diameter
    auto bfs_far = [&](int s) {
        vector<int> dist(N, -1);
        queue<int> q;
        q.push(s);
        dist[s] = 0;
        int far = s;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            far = v;
            for (int to : g[v]) {
                if (dist[to] == -1) {
                    dist[to] = dist[v] + 1;
                    q.push(to);
                }
            }
        }
        return pair<int, vector<int>>(far, dist);
    };

    auto p1 = bfs_far(0);
    auto p2 = bfs_far(p1.first);
    int diameter = 0;
    for (int d : p2.second) diameter = max(diameter, d);

    // Winner depends only on diameter parity:
    // odd diameter -> First wins, even diameter -> Second wins.
    cout << (diameter % 2 == 1 ? "Takahashi" : "Aoki") << '\n';
    return 0;
}
